from itertools import combinations
def clo(X, F):
    X = set(X); ch = True
    while ch:
        ch = False
        for l, r in F:
            if set(l) <= X and not set(r) <= X: X |= set(r); ch = True
    return X
def keys(U, F):
    sk = [set(c) for k in range(1, len(U)+1) for c in combinations(U, k) if clo(c, F) >= set(U)]
    return [k for k in sk if not any(o < k for o in sk)]
def nf(U, F):  # (2NF, 3NF, BCNF) using every X -> a in the closure
    K = keys(U, F); P = set().union(*K); r = [True]*3
    for k in range(1, len(U)+1):
        for X in combinations(U, k):
            if clo(X, F) >= set(U): continue
            for a in clo(X, F) - set(X):
                r[2] = False
                if a not in P:
                    r[1] = False
                    if any(set(X) < kk for kk in K): r[0] = False
    return r
