from collections import deque
fk = {'Sales': ['DateDim', 'Store', 'Product'], 'Shipments': ['DateDim', 'Warehouse', 'Product'],
      'Product': ['Brand']}
facts = ['Sales', 'Shipments']
copies_of_datedim = 1                      # one DateDim table listed, referenced by both facts
galaxy = len(facts) > 1 and bool(set(fk['Sales']) & set(fk['Shipments']))
snowflaked_product = 'Brand' in fk.get('Product', [])
def path(a, b):
    Qu, seen = deque([[a]]), {a}
    while Qu:
        p = Qu.popleft()
        if p[-1] == b: return p
        for n in fk.get(p[-1], []):
            if n not in seen: seen.add(n); Qu.append(p + [n])
res = {'A': copies_of_datedim == 2, 'B': galaxy, 'C': snowflaked_product,
       'D': path('Sales', 'Brand') == ['Sales', 'Product', 'Brand']}
print(sorted(k for k, v in res.items() if v))
